27	/// Tela 4 — Meus Registros, spec-4-1's real build: every `Entry`,
28	/// newest-first, grouped by day, each card marked by origin. Replaces the
29	/// former `MeusRegistrosPlaceholderScreen`.
30	///
31	/// [cubit] is a DI `lazySingleton` (Code Map) — this `StatefulWidget` never
32	/// closes it (`BlocProvider.value`, same convention
33	/// `AccountSettingsScreen` already uses for its own singleton cubit); only
34	/// this screen's own [ScrollController] is this `State`'s to dispose.
35	///
36	/// The global `ExpiryOverlayHost` shows its "Sessão expirada" dialog via
37	/// `showGeneralDialog` on the `Navigator` *above* this screen's own widget
38	/// subtree (`expiry_overlay_host.dart`) — this screen is never popped or
39	/// rebuilt from scratch underneath it, so [_scrollController]'s position
40	/// and [cubit]'s state survive that overlay appearing with no extra code
41	/// needed here (Acceptance Criteria's third bullet).
42	class MeusRegistrosScreen extends StatefulWidget {
43	  const MeusRegistrosScreen({
44	    required this.cubit,
45	    required this.searchCubit,
46	    super.key,
47	  });
48	
49	  final MeusRegistrosCubit cubit;
50	
51	  /// spec-5-1 — the permanently-docked `EntriesSearchBar`'s own cubit, a DI
52	  /// `lazySingleton` like [cubit] (Code Map); this `StatefulWidget` never
53	  /// closes it either, same rationale [cubit]'s own doc above gives.
54	  final EntriesSearchCubit searchCubit;
55	
56	  @override
57	  State<MeusRegistrosScreen> createState() => _MeusRegistrosScreenState();
58	}
59	
60	class _MeusRegistrosScreenState extends State<MeusRegistrosScreen> {
61	  // RNF01: no loading UI below 300ms — same threshold/`Timer` pattern as
62	  // `BootSplashScreen`.
63	  static const _skeletonThreshold = Duration(milliseconds: 300);
64	
65	  final ScrollController _scrollController = ScrollController();
66	  Timer? _skeletonTimer;
67	  bool _showSkeleton = false;
68	
69	  /// spec-5-1 — the search surface's own 300ms skeleton threshold,
70	  /// mirroring [_skeletonTimer]/[_showSkeleton] above but keyed off
71	  /// `EntriesSearchCubit`'s `ResourceLoading` rather than
72	  /// `MeusRegistrosLoading`: started fresh on every transition into
73	  /// `ResourceLoading` (`_onSearchStateChanged` below), since unlike the
74	  /// first-load timer above (started once, in [initState]) a search can
75	  /// enter/leave loading many times across one screen visit.
76	  Timer? _searchSkeletonTimer;
77	  bool _showSearchSkeleton = false;
78	
79	  /// Review fix (round 2, spec-4-4) — guards `_openDetail` against a rapid
80	  /// double-tap on a card pushing `/meus-registros/:id` twice (stacking two
81	  /// detail-route instances); cleared once the pushed route is popped, via
82	  /// `whenComplete` below.
83	  bool _navigatingToDetail = false;
84	
85	  @override
86	  void initState() {
87	    super.initState();
88	    widget.cubit.loadFirstPage();
89	    _skeletonTimer = Timer(_skeletonThreshold, () {
90	      if (mounted) {
91	        setState(() => _showSkeleton = true);
92	      }
93	    });
94	    _scrollController.addListener(_onScroll);
95	    // Review finding: `searchCubit` is a long-lived singleton (Code Map)
96	    // that can already be `ResourceLoading` the moment this `State` is
97	    // (re)created — e.g. the user switches tabs away mid-search and back,
98	    // which tears down and rebuilds this plain `GoRoute`'s widget while the
99	    // DI-singleton cubit keeps running. `BlocConsumer`'s `listener` below
100	    // only fires on a *new* state, never for one already current at
101	    // subscription time, so without this check the search skeleton would
102	    // never arm for an in-flight search resumed this way.
103	    if (widget.searchCubit.state is ResourceLoading<List<Entry>>) {
104	      _searchSkeletonTimer = Timer(_skeletonThreshold, () {
105	        if (mounted) {
106	          setState(() => _showSearchSkeleton = true);
107	        }
108	      });
109	    }
110	  }
111	
112	  @override
113	  void dispose() {
114	    _skeletonTimer?.cancel();
115	    _searchSkeletonTimer?.cancel();
116	    _scrollController
117	      ..removeListener(_onScroll)
118	      ..dispose();
119	    super.dispose();
120	  }
121	
122	  /// `BlocConsumer<EntriesSearchCubit, ...>`'s own listener (below) — starts
123	  /// [_searchSkeletonTimer] fresh on every transition into
124	  /// `ResourceLoading`, mirroring [initState]'s one-shot [_skeletonTimer]
125	  /// but re-armed per search rather than once per screen visit; any other
126	  /// state (including a fast resolve before the 300ms threshold, RNF01)
127	  /// cancels it and resets [_showSearchSkeleton].
128	  void _onSearchStateChanged(
129	    BuildContext context,
130	    Resource<List<Entry>> state,
131	  ) {
132	    _searchSkeletonTimer?.cancel();
133	    if (state is ResourceLoading<List<Entry>>) {
134	      _searchSkeletonTimer = Timer(_skeletonThreshold, () {
135	        if (mounted) {
136	          setState(() => _showSearchSkeleton = true);
137	        }
138	      });
139	      return;
140	    }
141	    if (_showSearchSkeleton) {
142	      setState(() => _showSearchSkeleton = false);
143	    }
144	  }
145	
146	  void _openDetail(Entry entry) {
147	    if (_navigatingToDetail) {
148	      return;
149	    }
150	    _navigatingToDetail = true;
151	    context
152	        .push(
153	          '${AppRoutePaths.meusRegistros}/'
154	          '${Uri.encodeComponent(entry.id)}',
155	        )
156	        .whenComplete(() {
157	          if (mounted) {
158	            setState(() => _navigatingToDetail = false);
159	          } else {
160	            _navigatingToDetail = false;
161	          }
162	        });
163	  }
164	
165	  void _onScroll() {
166	    if (!_scrollController.hasClients) {
167	      return;
168	    }
169	    final position = _scrollController.position;
170	    // Pre-fetches a little before the exact end (reusing `spacing2xl`
171	    // purely as a scroll-distance buffer, not a new literal) for a
172	    // smoother scroll-pagination feel; `loadMore()` itself is a no-op once
173	    // there's no further page or a call is already in flight.
174	    if (position.pixels >= position.maxScrollExtent - DesignTokens.spacing2xl) {
175	      widget.cubit.loadMore();
176	    }
177	  }
178	
179	  @override
180	  Widget build(BuildContext context) {
181	    return MultiBlocProvider(
182	      providers: [
183	        BlocProvider.value(value: widget.cubit),
184	        BlocProvider.value(value: widget.searchCubit),
185	      ],
186	      child: Scaffold(
187	        backgroundColor: DesignTokens.colorSurfaceBg,
188	        body: Column(
189	          children: [
190	            const BackArrowHeader(title: 'Meus Registros'),
191	            Padding(
192	              padding: const EdgeInsets.fromLTRB(
193	                DesignTokens.spacingMd,
194	                DesignTokens.spacingMd,
195	                DesignTokens.spacingMd,
196	                0,
197	              ),
198	              child: EntriesSearchBar(onChanged: widget.searchCubit.onQueryChanged),
199	            ),
200	            Expanded(
201	              child: BlocConsumer<EntriesSearchCubit, Resource<List<Entry>>>(
202	                listener: _onSearchStateChanged,
203	                builder: (context, searchState) {
204	                  // Boundaries: "an empty query reverts to the normal
205	                  // timeline" — `ResourceIdle` is the only variant that
206	                  // falls through to the pre-existing
207	                  // `MeusRegistrosCubit`-driven timeline below; every other
208	                  // variant renders the search surface instead.
209	                  if (searchState is ResourceIdle<List<Entry>>) {
210	                    return BlocBuilder<MeusRegistrosCubit, MeusRegistrosState>(
211	                      builder: (context, state) => switch (state) {
212	                        MeusRegistrosLoading() =>
213	                          _showSkeleton
214	                              ? const _SkeletonList()
215	                              : const SizedBox.shrink(),
216	                        MeusRegistrosEmpty() => const _EmptyState(),
217	                        MeusRegistrosError(message: final message) =>
218	                          _ErrorState(
219	                            message: message,
220	                            onRetry: widget.cubit.loadFirstPage,
221	                          ),
222	                        MeusRegistrosLoaded() => _EntryList(
223	                          state: state,
224	                          scrollController: _scrollController,
225	                          onRetryLoadMore: widget.cubit.retryLoadMore,
226	                          onRetryTap: (entry) => widget.cubit.retry(entry.id),
227	                          onCardTap: _openDetail,
228	                        ),
229	                      },
230	                    );
231	                  }
232	                  return _SearchResults(
233	                    state: searchState,
234	                    showSkeleton: _showSearchSkeleton,
235	                    onCardTap: _openDetail,
236	                  );
237	                },
238	              ),
239	            ),
240	          ],
241	        ),
242	      ),
243	    );
244	  }
245	}
246	
247	/// spec-5-1's own search-results surface — `EntriesSearchCubit`'s
248	/// `Resource<List<Entry>>` rendered in place of the timeline whenever
249	/// [state] isn't `ResourceIdle` (the screen's own `build` filters that
250	/// variant out before ever reaching here). Every result here is always a
251	/// server-confirmed [Entry] (`EntriesRepository.search()`'s own contract —
252	/// no cache fallback, no pending-write overlay), so every card's badge is
253	/// unconditionally [SyncBadgeState.synchronized] — never recomputed via
254	/// `deriveSyncBadgeState()` (Never: "any screen recomputing badge state
255	/// inline" extends here too, there is simply no pending/offline state for
256	/// a search result to derive).
257	class _SearchResults extends StatelessWidget {
258	  const _SearchResults({
259	    required this.state,
260	    required this.showSkeleton,
261	    required this.onCardTap,
262	  });
263	
264	  final Resource<List<Entry>> state;
265	  final bool showSkeleton;
266	  final void Function(Entry entry) onCardTap;
267	
268	  @override
269	  Widget build(BuildContext context) {
270	    return switch (state) {
271	      ResourceIdle<List<Entry>>() =>
272	        // Unreachable — `MeusRegistrosScreen.build` never routes
273	        // `ResourceIdle` here — kept only so this switch stays exhaustive.
274	        const SizedBox.shrink(),
275	      ResourceLoading<List<Entry>>() =>
276	        showSkeleton ? const _SkeletonList() : const SizedBox.shrink(),
277	      ResourceError<List<Entry>>(failure: final failure) =>
278	        _SearchErrorState(message: failure.message),
279	      ResourceData<List<Entry>>(data: final entries) => entries.isEmpty
280	          ? const _EmptySearchResults()
281	          : ListView.builder(
282	              padding: DesignTokens.screenPadding,
283	              itemCount: entries.length,
284	              itemBuilder: (context, index) {
285	                final entry = entries[index];
286	                return Padding(
287	                  key: ValueKey(entry.id),
288	                  padding: const EdgeInsets.only(
289	                    bottom: DesignTokens.spacingSm,
290	                  ),
291	                  child: EntryRecordCard(
292	                    entry: entry,
293	                    badgeState: const SyncBadgeState.synchronized(),
294	                    onTap: () => onCardTap(entry),
295	                  ),
296	                );
297	              },
298	            ),
299	    };
300	  }
301	}
302	
303	/// `ResourceError<List<Entry>>`'s own rendering (spec-5-1 I/O matrix:
304	/// "ResourceError(networkOffline) rendered") — just the message, unlike
305	/// [_ErrorState] above: there is no retry affordance named for search
306	/// anywhere in Boundaries/the I/O matrix, since the user's own next
307	/// keystroke (re-debounced through `EntriesSearchCubit`) is what retries,
308	/// never an explicit button.
309	class _SearchErrorState extends StatelessWidget {
310	  const _SearchErrorState({required this.message});
311	
312	  final String message;
313	
314	  @override
315	  Widget build(BuildContext context) {
