429	  void _onPhotoStateChange(BuildContext context, PhotoCaptureState state) {
430	    if (state is PhotoRecognized && state.path != _lastSyncedPhotoPath) {
431	      _lastSyncedPhotoPath = state.path;
432	      _photoTextController.text = state.text;
433	    }
434	    final kind = _photoAnnounceKindOf(state);
435	    if (kind == _lastPhotoAnnouncedKind) {
436	      return;
437	    }
438	    _lastPhotoAnnouncedKind = kind;
439	    switch (state) {
440	      case PhotoProcessing():
441	        _announce('Reconhecendo texto da foto');
