452	          _announce('Registro salvo').then((_) {
453	            if (context.mounted) {
454	              _unfocusAndPop(context);
455	            }
456	          }),
457	        );
458	      case PhotoIdle():
459	        // Reachable via `cancel()` resetting from `PhotoProcessing` (a
