1278	class _WaveformState extends State<_Waveform> {
1279	  // `growable: true` — `build()` below reads this with `removeAt`/`add`
1280	  // on every new amplitude sample, which `List.filled`'s own default
1281	  // fixed-length list doesn't support.
1282	  final List<double> _samples = List.filled(
1283	    _waveformBarCount,
1284	    0.1,
1285	    growable: true,
1286	  );
1287	  StreamSubscription<double>? _subscription;
1288	
1289	  @override
1290	  void initState() {
1291	    super.initState();
1292	    _subscription = widget.amplitudeStream?.listen(
1293	      (amplitude) {
1294	        if (!mounted) {
1295	          return;
1296	        }
1297	        setState(() {
1298	          _samples.removeAt(0);
1299	          // `num.clamp` returns `num`, not `double` — `_samples` is
1300	          // `List<double>`.
1301	          _samples.add(amplitude.clamp(0.1, 1.0).toDouble());
1302	        });
1303	      },
1304	      // Review finding: an unhandled `onError` turns a native amplitude-
1305	      // stream error into an uncaught async exception — the waveform
1306	      // just stays frozen on its last sample instead, no worse than the
1307	      // already-handled "no live stream" (frozen/processing) case.
1308	      onError: (_) {},
1309	    );
1310	  }
1311	
1312	  @override
1313	  void dispose() {
1314	    _subscription?.cancel();
1315	    super.dispose();
1316	  }
1317	
1318	  @override
1319	  Widget build(BuildContext context) {
1320	    return Opacity(
1321	      opacity: widget.opacity,
1322	      child: SizedBox(
1323	        height: DesignTokens.audioWaveformHeight,
1324	        child: Row(
1325	          mainAxisAlignment: MainAxisAlignment.center,
1326	          crossAxisAlignment: CrossAxisAlignment.center,
1327	          children: [
1328	            for (var i = 0; i < _samples.length; i++) ...[
1329	              AnimatedContainer(
1330	                duration: DesignTokens.durationSheetUp,
1331	                width: DesignTokens.audioWaveformBarWidth,
1332	                height: DesignTokens.audioWaveformHeight * _samples[i],
1333	                decoration: const BoxDecoration(
1334	                  // Prototype: the bars themselves are `colorSecondary`
1335	                  // (olive green) — only the recording timer text is
1336	                  // `colorError` (correction; a previous pass swapped the
1337	                  // two). A small, fixed corner radius (not [radiusFull])
1338	                  // keeps every bar reading as a bar rather than a dot at
1339	                  // low amplitude.
1340	                  color: DesignTokens.colorSecondary,
1341	                  borderRadius: BorderRadius.all(
1342	                    Radius.circular(DesignTokens.audioWaveformBarRadius),
1343	                  ),
1344	                ),
1345	              ),
1346	              if (i < _samples.length - 1)
1347	                const SizedBox(width: DesignTokens.audioWaveformBarGap),
