104	/// A controllable `PendingEntryWriteTracker` fake — lets a test drive
105	/// [pendingWrites]/[confirmedWrites] directly (simulating a capture cubit
106	/// elsewhere, sharing the same tracker instance in production) and records
107	/// every [retry] call so `MeusRegistrosCubit.retry()`'s own delegation can
108	/// be asserted without a real `EntriesRepository` behind it.
109	class _FakePendingEntryWriteTracker implements PendingEntryWriteTracker {
110	  final _pendingController =
111	      StreamController<List<PendingEntryWrite>>.broadcast();
112	  final _confirmedController =
113	      StreamController<({String tempId, Entry entry})>.broadcast();
114	  final List<String> retryCalls = [];
115	
116	  void emitPendingWrites(List<PendingEntryWrite> writes) =>
117	      _pendingController.add(writes);
118	
119	  void emitConfirmed(String tempId, Entry entry) =>
120	      _confirmedController.add((tempId: tempId, entry: entry));
121	
122	  @override
123	  Stream<List<PendingEntryWrite>> get pendingWrites =>
124	      _pendingController.stream;
125	
126	  @override
127	  Stream<({String tempId, Entry entry})> get confirmedWrites =>
128	      _confirmedController.stream;
129	
130	  @override
131	  Future<Either<Failure, Entry>> create({
132	    required String content,
133	    required EntrySource source,
134	    int? mediaDurationSeconds,
135	  }) async => throw UnimplementedError('not expected to be called');
136	
137	  @override
138	  Future<void> retry(String tempId) async {
139	    retryCalls.add(tempId);
140	  }
141	
142	  @override
143	  Future<void> dispose() async {
144	    await _pendingController.close();
145	    await _confirmedController.close();
146	  }
147	}
