76	/// A plain (non-mocktail) fake — queues one `list()` result per call, same
77	/// rationale as `meus_registros_cubit_test.dart`'s own fake, plus an
78	/// optional [firstCallGate] so a test can hold the very first `list()`
79	/// call unresolved to observe the skeleton's 300ms threshold.
80	class _FakeEntriesRepository implements EntriesRepository {
81	  final List<Either<Failure, EntriesPage>> _listResults = [];
82	  int listCallCount = 0;
83	  Completer<void>? firstCallGate;
84	
85	  /// spec-5-1 — queued `search()` results, same per-call-queue convention
86	  /// as [_listResults] above. This file's own tests never queue one
87	  /// unless they specifically exercise the new docked search bar.
88	  final List<Either<Failure, List<Entry>>> _searchResults = [];
89	  final List<String> searchCalls = [];
90	
91	  /// spec-5-1 — same [firstCallGate] rationale as `list()`'s own gate,
92	  /// applied to `search()` instead: lets a test hold the search call
93	  /// unresolved to observe `_searchSkeletonTimer`'s own 300ms threshold
94	  /// (Matrix: "Slow request"). Every queued test only ever makes one
95	  /// `search()` call, so gating unconditionally (unlike [firstCallGate]'s
96	  /// call-count check) is sufficient.
97	  Completer<void>? searchGate;
98	
99	  void queueList(Either<Failure, EntriesPage> result) {
100	    _listResults.add(result);
101	  }
102	
103	  void queueSearch(Either<Failure, List<Entry>> result) {
104	    _searchResults.add(result);
105	  }
106	
107	  @override
108	  Future<Either<Failure, Entry>> create({
109	    required String content,
110	    required EntrySource source,
111	    int? mediaDurationSeconds,
112	  }) async => throw UnimplementedError('not expected to be called');
113	
114	  @override
115	  Future<Either<Failure, EntriesPage>> list({
116	    String? cursor,
117	    int limit = 20,
118	  }) async {
119	    listCallCount++;
120	    if (listCallCount == 1 && firstCallGate != null) {
121	      await firstCallGate!.future;
122	    }
123	    if (_listResults.isEmpty) {
124	      throw StateError('no queued list() result for call #$listCallCount');
125	    }
126	    return _listResults.removeAt(0);
127	  }
128	
129	  @override
130	  Future<Either<Failure, Entry>> getById(String id) async =>
131	      throw UnimplementedError('not expected to be called');
132	
133	  @override
134	  Future<Either<Failure, List<Entry>>> search(String query) async {
135	    searchCalls.add(query);
136	    if (searchGate != null) {
137	      await searchGate!.future;
138	    }
139	    if (_searchResults.isEmpty) {
140	      throw StateError(
141	        'no queued search() result for call #${searchCalls.length}',
142	      );
143	    }
144	    return _searchResults.removeAt(0);
145	  }
146	}
