306	    final result = await _repository.list(
307	      cursor: current.nextCursor,
308	      source: _activeSource,
309	      dateFrom: _activeDateFrom,
310	      dateTo: _activeDateTo,
311	    );
312	    if (isClosed || generation != _generation) {
313	      return;
314	    }
315	    // Re-reads `state` rather than closing over `current` — defensive
316	    // against `loadFirstPage()` having reset the state to something other
317	    // than `MeusRegistrosLoaded` while this await was pending.
318	    final latest = state;
319	    if (latest is! MeusRegistrosLoaded) {
320	      return;
321	    }
322	    result.match(
323	      (failure) =>
324	          emit(latest.copyWith(isLoadingMore: false, loadMoreFailed: true)),
325	      (page) {
326	        // I/O matrix: "Next page appended, no dup ids" — defensive
327	        // de-duplication in case a cursor-boundary entry is ever repeated
328	        // by the server, including a repeat *within* this same page
329	        // (`dedupedById`'s running `seenIds` set covers both).
330	        final seenIds = latest.entries.map((entry) => entry.id).toSet();
331	        final newEntries = dedupedById(
332	          page.items,
333	          (entry) => entry.id,
334	          seenIds: seenIds,
335	        );
336	        // Defensive guard against a degenerate server response: if every
337	        // item in this "successful" page was already present by id (zero
338	        // genuinely-new entries) yet the server still reports a non-null
339	        // `nextCursor`, treat the page as exhausted rather than trusting
340	        // that cursor — otherwise a misbehaving/stuck server cursor could
341	        // make the scroll listener keep re-triggering `loadMore()`
342	        // indefinitely with no progress.
343	        final nextCursor = newEntries.isEmpty ? null : page.nextCursor;
344	        emit(
345	          MeusRegistrosLoaded(
346	            entries: [...latest.entries, ...newEntries],
347	            nextCursor: nextCursor,
348	            pendingWrites: latest.pendingWrites,
349	          ),
350	        );
351	      },
352	    );
353	  }
354	
355	  @override
356	  Future<void> close() async {
357	    await _pendingSubscription.cancel();
358	    await _confirmedSubscription.cancel();
359	    return super.close();
360	  }
361	}
362

