1	import 'package:flutter_test/flutter_test.dart';
2	import 'package:fpdart/fpdart.dart';
3	import 'package:hive_ce/hive_ce.dart';
4	import 'package:mocktail/mocktail.dart';
5	
6	import 'package:cerne/core/failure/failure.dart';
7	import 'package:cerne/features/entries/data/datasources/entries_remote_data_source.dart';
8	import 'package:cerne/features/entries/data/models/entry_dto.dart';
9	import 'package:cerne/features/entries/data/repositories/entries_repository_impl.dart';
10	import 'package:cerne/features/entries/domain/entities/entry.dart';
11	
12	class MockEntriesRemoteDataSource extends Mock
13	    implements EntriesRemoteDataSource {}
14	
15	class MockBox extends Mock implements Box<Map> {}
16	
17	const _dto = EntryDto(
18	  id: 'e1',
19	  content: 'Hoje foi um bom dia.',
20	  source: EntrySource.manual,
21	  chatMessageId: null,
22	  occurredAt: '2026-01-01T00:00:00Z',
23	  serverRevision: 1,
24	  createdAt: '2026-01-01T00:00:00Z',
25	  updatedAt: '2026-01-01T00:00:00Z',
26	);
27	
28	EntryDto _listDto(String id, String occurredAt) => EntryDto(
29	  id: id,
30	  content: 'content-$id',
31	  source: EntrySource.manual,
32	  chatMessageId: null,
33	  occurredAt: occurredAt,
34	  serverRevision: 1,
35	  createdAt: occurredAt,
36	  updatedAt: occurredAt,
37	);
38	
39	/// Covers spec-3-1's I/O & Edge-Case Matrix for `EntriesRepository.create`:
40	/// - success -> maps the `EntryDto` to `Entry` and writes it through to
41	///   the Hive box, keyed by id, *before* returning `Right`.
42	/// - failure (incl. offline) -> `Left(Failure)`, the box is never touched.
43	void main() {
44	  late MockEntriesRemoteDataSource mockRemoteDataSource;
45	  late MockBox mockBox;
46	  late EntriesRepositoryImpl repository;
47	
48	  setUpAll(() {
49	    registerFallbackValue(EntrySource.manual);
50	  });
51	
52	  setUp(() {
53	    mockRemoteDataSource = MockEntriesRemoteDataSource();
54	    mockBox = MockBox();
55	    when(() => mockBox.put(any(), any())).thenAnswer((_) async {});
56	    when(() => mockBox.putAll(any())).thenAnswer((_) async {});
57	    repository = EntriesRepositoryImpl(
58	      remoteDataSource: mockRemoteDataSource,
59	      entriesBox: mockBox,
60	    );
61	  });
62	
63	  group('create() — success', () {
64	    test('writes EntryDto.toJson() to the Hive box keyed by id, then returns '
65	        'Right(Entry) mapped from the dto', () async {

250	  group('list() — offline/timeout fallback (Boundaries)', () {
251	    test(
252	      'networkOffline falls back to a full Hive box dump, sorted '
253	      'occurredAt desc, with nextCursor: null — never propagated as Left',
254	      () async {
255	        when(
256	          () => mockRemoteDataSource.list(
257	            cursor: any(named: 'cursor'),
258	            limit: any(named: 'limit'),
259	          ),
260	        ).thenAnswer(
261	          (_) async => left(const Failure.networkOffline(message: 'Offline')),
262	        );
263	        when(() => mockBox.values).thenReturn([
264	          _listDto('older', '2026-01-01T00:00:00Z').toJson(),
265	          _listDto('newer', '2026-01-03T00:00:00Z').toJson(),
266	          _listDto('middle', '2026-01-02T00:00:00Z').toJson(),
267	        ]);
268	
269	        final result = await repository.list();
270	
271	        expect(result.isRight(), isTrue);
272	        result.match((_) => fail('expected Right'), (page) {
273	          expect(page.items.map((e) => e.id), ['newer', 'middle', 'older']);
274	          expect(page.nextCursor, isNull);
275	        });
276	      },
277	    );
278	
279	    test('networkTimeout triggers the exact same cache fallback', () async {
280	      when(
281	        () => mockRemoteDataSource.list(
282	          cursor: any(named: 'cursor'),
283	          limit: any(named: 'limit'),
284	        ),
285	      ).thenAnswer(
286	        (_) async => left(const Failure.networkTimeout(message: 'Timed out')),
287	      );
288	      when(() => mockBox.values)
289	          .thenReturn([_listDto('e1', '2026-01-01T00:00:00Z').toJson()]);
290	
291	      final result = await repository.list();
292	
293	      expect(result.isRight(), isTrue);
294	      result.match((_) => fail('expected Right'), (page) {
295	        expect(page.items.single.id, 'e1');
296	        expect(page.nextCursor, isNull);
297	      });
298	    });
299	
300	    test('an empty Hive box falls back to an empty EntriesPage, not an '
301	        'error', () async {
302	      when(
303	        () => mockRemoteDataSource.list(
304	          cursor: any(named: 'cursor'),
305	          limit: any(named: 'limit'),
306	        ),
307	      ).thenAnswer(
308	        (_) async => left(const Failure.networkOffline(message: 'Offline')),
309	      );
310	      when(() => mockBox.values).thenReturn(const []);
311	
312	      final result = await repository.list();
313	
314	      result.match((_) => fail('expected Right'), (page) {
315	        expect(page.items, isEmpty);
316	        expect(page.nextCursor, isNull);
317	      });
318	    });
319	
320	    test('a corrupt cached entry (malformed occurredAt, unsortable) maps to '
321	        'Left(malformedResponse) rather than throwing', () async {
322	      when(
323	        () => mockRemoteDataSource.list(
324	          cursor: any(named: 'cursor'),
325	          limit: any(named: 'limit'),
326	        ),
327	      ).thenAnswer(
328	        (_) async => left(const Failure.networkOffline(message: 'Offline')),
329	      );
330	      when(() => mockBox.values).thenReturn([
331	        _listDto('good', '2026-01-01T00:00:00Z').toJson(),
332	        _listDto('bad', 'not-a-date').toJson(),
333	      ]);
334	
335	      final result = await repository.list();
336	
337	      expect(result.isLeft(), isTrue);
338	      result.match(
339	        (failure) => expect(failure, isA<MalformedResponse>()),
340	        (_) => fail('expected Left'),
341	      );
342	    });
343	
344	    test('every other Failure (e.g. authExpired) propagates as Left, '
345	        'unmapped — the Hive box is never read', () async {
346	      when(
347	        () => mockRemoteDataSource.list(
348	          cursor: any(named: 'cursor'),
349	          limit: any(named: 'limit'),
350	        ),
351	      ).thenAnswer(
352	        (_) async =>
353	            left(const Failure.authExpired(message: 'Sessão expirada')),
354	      );
355	
356	      final result = await repository.list();
357	
358	      expect(result.isLeft(), isTrue);
359	      result.match(
360	        (failure) => expect(failure, isA<AuthExpired>()),
361	        (_) => fail('expected Left'),
362	      );
363	      verifyNever(() => mockBox.values);
364	    });
365	
366	    test(
367	      'Design Notes clarification: a paginated call (cursor != null) that '
368	      'fails with networkOffline propagates as Left, unmapped — the Hive '
369	      'box is never read, so loadMore()\'s own loadMoreFailed/retry path '
370	      'handles it instead of a full unrelated cache dump silently '
371	      'replacing the in-progress paginated list',
372	      () async {
373	        when(
374	          () => mockRemoteDataSource.list(
375	            cursor: any(named: 'cursor'),
