/// forwards whatever [EntriesRepository.list]'s own caller already
/// resolved. Returns the raw page as a record — no dedicated DTO
/// wrapper type, since `EntriesRepositoryImpl.list()` is this record's
/// only reader.
Future<Either<Failure, ({List<EntryDto> items, String? nextCursor})>> list({
  String? cursor,
  int limit = 20,
  EntrySource? source,
  DateTime? dateFrom,
  DateTime? dateTo,
}) async {
  final result = await _apiClient.get(
    'entries-list',
    queryParameters: {
      'limit': limit,
      'cursor': ?cursor,
      'source': ?source?.name,
      'dateFrom': ?dateFrom?.toIso8601String(),
      'dateTo': ?dateTo?.toIso8601String(),
    },
  );

